      "title.home": "Dabot — la communauté, organisée",
      "title.privacy": "Confidentialité — Dabot",
      "title.terms": "Conditions — Dabot",
      "title.premium": "Premium — Dabot",
      "title.community": "Communauté — Dabot",
      "title.levels": "Niveaux — Dabot",
      "title.rules": "Règles — Dabot",
