      "title.home": "Dabot — コミュニティを整理",
      "title.privacy": "プライバシー — Dabot",
      "title.terms": "利用規約 — Dabot",
      "title.premium": "Premium — Dabot",
      "title.community": "コミュニティ — Dabot",
      "title.levels": "レベル — Dabot",
      "title.rules": "ルール — Dabot",
